import React, { useState, useMemo, useEffect, useContext } from 'react';
import { StaffRolesContext } from '../StaffRolesContext'; // Ensure this path is correct

/**
 * ActivityAllocationTab Component
 * * Manages workload for repeatable small-group activities like tutorials or labs.
 * Allows users to define multiple activities, calculate allocations for each,
 * and distribute the workload among various staff roles.
 */
const ActivityAllocationTab = ({ term, onAllocationChange }) => {
    // Get available staff roles from the context
    const { staffRoles } = useContext(StaffRolesContext);

    // Combine default and custom roles for the distribution table columns
     const staffColumns = useMemo(() => {
        // FIX: Add a fallback to an empty array to prevent .map() on undefined
        const roles = staffRoles || [];
        return ['Subject Coordinator', ...roles.map(r => r.role)];
    }, [staffRoles]);

    // Initial state with one default activity based on the screenshot
    const [activities, setActivities] = useState([
        {
            id: 1,
            activityName: 'Tutorial',
            numberOfGroups: 5,
            maxGroupSize: 25,
            weeklyClassTime: 2,
            justification: '',
            distribution: {}, // { role: { 'Task': value, ... } }
        },
    ]);

    // useMemo for efficient recalculation of allocations whenever dependencies change
    const calculatedData = useMemo(() => {
        const termMultiplier = term === 'Autumn' ? 1.0 : 0.923;
        let grandTotal = 0;

        const activityAllocations = activities.map(activity => {
            const numGroups = Number(activity.numberOfGroups) || 0;
            const classTime = Number(activity.weeklyClassTime) || 0;
            const allocation = numGroups * classTime * termMultiplier * 0.0125;
            grandTotal += allocation;
            return { id: activity.id, allocation };
        });

        return { grandTotal, activityAllocations };
    }, [activities, term]);

    // useEffect to notify the parent component of the total allocation change
    useEffect(() => {
        if (onAllocationChange) {
            onAllocationChange(calculatedData.grandTotal);
        }
    }, [calculatedData.grandTotal, onAllocationChange]);

    // --- Event Handlers ---

    const handleInputChange = (id, field, value) => {
        setActivities(prev =>
            prev.map(activity =>
                activity.id === id ? { ...activity, [field]: value } : activity
            )
        );
    };

    const handleDistributionChange = (id, role, task, value) => {
        const numericValue = Number(value) / 100 || 0; // Convert percentage from input to a decimal
        setActivities(prev =>
            prev.map(act => {
                if (act.id !== id) return act;
                const newDistribution = { ...(act.distribution || {}) };
                if (!newDistribution[role]) newDistribution[role] = {};
                newDistribution[role][task] = numericValue;
                return { ...act, distribution: newDistribution };
            })
        );
    };

    const handleAddActivity = () => {
        const newId = activities.length > 0 ? Math.max(...activities.map(a => a.id)) + 1 : 1;
        setActivities(prev => [
            ...prev,
            {
                id: newId,
                activityName: `Activity ${newId}`,
                numberOfGroups: '',
                maxGroupSize: '',
                weeklyClassTime: '',
                justification: '',
                distribution: {},
            },
        ]);
    };


    return (
        <div style={styles.container}>
            <div style={styles.header}>
                <h3 style={styles.title}>Activity Allocation ⓘ</h3>
                <button style={styles.addButton} onClick={handleAddActivity}>+ Add</button>
            </div>

            {activities.map((activity) => {
                const allocationResult = calculatedData.activityAllocations.find(a => a.id === activity.id);
                const activityAllocation = allocationResult ? allocationResult.allocation : 0;

                // For validation: sum up all values in the activity's distribution table
                const distributionSum = Object.values(activity.distribution || {}).reduce(
                    (total, tasks) => total + Object.values(tasks).reduce((sum, val) => sum + (val || 0), 0), 0
                );
                const isDistributionInvalid = distributionSum > 0.0125;

                return (
                    <div key={activity.id} style={styles.activityCard}>
                        {/* Activity Header */}
                        <div style={styles.activityHeader}>
                            <input
                                type="text"
                                value={activity.activityName}
                                onChange={(e) => handleInputChange(activity.id, 'activityName', e.target.value)}
                                style={styles.activityNameInput}
                            />
                        </div>

                        {/* Top Inputs Section */}
                        <div style={styles.inputGrid}>
                            <div>
                                <label style={styles.label}>Total Allocation</label>
                                <input
                                    style={{...styles.input, backgroundColor: '#e9ecef'}}
                                    type="text"
                                    readOnly
                                    value={`${(activityAllocation * 100).toFixed(1)}%`}
                                />
                            </div>
                            <div>
                                <label style={styles.label}>Number of groups</label>
                                <input
                                    style={styles.input}
                                    type="number"
                                    min="0"
                                    value={activity.numberOfGroups}
                                    onChange={(e) => handleInputChange(activity.id, 'numberOfGroups', e.target.value)}
                                />
                            </div>
                            <div>
                                <label style={styles.label}>Max group size per curriculum approval documents</label>
                                <input
                                    style={styles.input}
                                    type="number"
                                    min="0"
                                    value={activity.maxGroupSize}
                                    onChange={(e) => handleInputChange(activity.id, 'maxGroupSize', e.target.value)}
                                />
                            </div>
                             <div>
                                <label style={styles.label}>Weekly class time per group over 12 weeks in hours</label>
                                <input
                                    style={styles.input}
                                    type="number"
                                    min="0"
                                    step="0.5"
                                    value={activity.weeklyClassTime}
                                    onChange={(e) => handleInputChange(activity.id, 'weeklyClassTime', e.target.value)}
                                />
                            </div>
                        </div>

                        {/* Distribution Table Section */}
                        <h4 style={styles.subHeader}>Allocation per weekly hour per group</h4>
                        {isDistributionInvalid && <p style={styles.errorMessage}>Maximum allocation per weekly hour exceeded. Sum must not be more than 1.25%.</p>}

                        <div style={{overflowX: 'auto'}}>
                            <table style={styles.table}>
                                <thead>
                                    <tr>
                                        <th style={{...styles.th, minWidth: '50px'}}>Actions</th>
                                        <th style={{...styles.th, minWidth: '200px'}}>Staff Role</th>
                                        <th style={{...styles.th, minWidth: '150px'}}>Preparation / Setup</th>
                                        <th style={{...styles.th, minWidth: '150px'}}>Delivery / Supervision</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {staffColumns.map(role => {
                                        const prepValue = activity.distribution?.[role]?.['Preparation / Setup'] || 0;
                                        const deliveryValue = activity.distribution?.[role]?.['Delivery / Supervision'] || 0;

                                        return (
                                            <tr key={role}>
                                                <td style={styles.td}>
                                                    <span style={{cursor: 'pointer'}}>✏️</span>
                                                </td>
                                                <td style={styles.td}>{role}</td>
                                                <td style={styles.td}>
                                                    <input
                                                        type="number"
                                                        style={styles.tableInput}
                                                        value={prepValue ? (prepValue * 100).toFixed(2) : ''}
                                                        onChange={(e) => handleDistributionChange(activity.id, role, 'Preparation / Setup', e.target.value)}
                                                        placeholder="0.00%"
                                                        step="0.01"
                                                    />
                                                </td>
                                                <td style={styles.td}>
                                                    <input
                                                        type="number"
                                                        style={styles.tableInput}
                                                        value={deliveryValue ? (deliveryValue * 100).toFixed(2) : ''}
                                                        onChange={(e) => handleDistributionChange(activity.id, role, 'Delivery / Supervision', e.target.value)}
                                                        placeholder="0.00%"
                                                        step="0.01"
                                                    />
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                );
            })}
             <div style={styles.footer}>
                 <button style={styles.saveButton}>💾 Save</button>
             </div>
        </div>
    );
};

